#include "InstrumentBody.h"
#include <filesystem>
#include <fstream>
#include <vector>
#include <string>
#include <cmath>
#include <cstdio>

int main(int argc, char** argv)
{
    if (argc != 2) return 2;
    std::filesystem::create_directories(argv[1]);
    constexpr int rate = 96000;
    for (int model : {cs80::body::piano, cs80::body::tine, cs80::body::reed,
                      cs80::body::nylon, cs80::body::steel, cs80::body::bass})
    {
        const int low = model == cs80::body::nylon || model == cs80::body::steel ? 40
                      : model == cs80::body::bass ? 28 : 36;
        for (int note : {low, low + 12, low + 24})
            for (int velocity : {25, 85})
            {
                cs80::body::InstrumentBody body;
                body.prepare(rate, 48000.0);
                body.noteOn(model, static_cast<float>(note), velocity / 100.0f, .8f, 1.0f, 12345);
                const float freq = static_cast<float>(440.0 * std::exp2((note - 69) / 12.0));
                std::vector<float> audio(static_cast<size_t>(1.45 * rate));
                for (float& sample : audio)
                {
                    sample = body.tick(freq, .8f, 0.0f);
                    if (!std::isfinite(sample)) return 3;
                }
                const std::string name = std::to_string(model) + "_" + std::to_string(note)
                                       + "_" + std::to_string(velocity) + ".f32";
                std::ofstream out(std::filesystem::path(argv[1]) / name, std::ios::binary);
                out.write(reinterpret_cast<const char*>(audio.data()),
                          static_cast<std::streamsize>(audio.size() * sizeof(float)));
                if (!out) return 4;
            }
    }
    std::puts("36 direct-body fixtures rendered; all finite");
}
